import './cloud-sync.js';
import{SPATIAL_TRACKS,SPATIAL_CHAIN,SPATIAL_DIAGNOSTIC,recommendSpatialTrack,rotateCellsClockwise,sameCells,frontView,sideView,countCubes,fitsClues,displayRowsBackToFront,spatialChoiceIndex,freshSpatialChoiceIndex,createBlankSpatialLearner}from'./spatial-data.js?v=spatial1';

const $=s=>document.querySelector(s),storageKey='mathlab-spatial-v1',memory={};
function blankStore(){return{a:createBlankSpatialLearner(),b:createBlankSpatialLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankSpatialLearner(),hintLevel=0,errors=0,sessionMissionId=null,work={};
function ensureState(){const blank=createBlankSpatialLearner();state={...blank,...state,diagnostic:{...blank.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...blank.evidence,...state.evidence},family:{...blank.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function saveLearnerChoice(){store={...readStore(),learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store))}catch{}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return SPATIAL_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[SPATIAL_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{errors:0,hints:0,work:{}};errors=Number(saved.errors)||0;hintLevel=Number(saved.hints)||0;work=saved.work||{}}
function saveSession(nextWork=work){if(!sessionMissionId)return;work=nextWork;state.sessions[sessionMissionId]={errors,hints:hintLevel,work};save()}
function miss(message){errors++;saveSession();feedback(message,'try')}
function complete(i,dims=[],pending=false,preview=false){const m=SPATIAL_CHAIN.missions[i],completedSession=sessionMissionId;state.missions[m.id]={complete:!preview,preview,errors,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.transfer=state.evidence.transfer==='unknown'?'learning':state.evidence.transfer}if(preview)state.previewFresh=false;if(!preview&&i<4)state.activeMission=i+1;if(completedSession)delete state.sessions[completedSession];errors=0;hintLevel=0;work={};sessionMissionId=null;save();setTimeout(render,420)}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}

function cellBoard(pattern,label='Pattern'){const cells=new Set(pattern.cells.map(x=>x.join(','))),positions=pattern.cells.map(([r,c])=>`row ${r+1} column ${c+1}`).join(', ');return `<div class="spatial-pattern" role="img" aria-label="${esc(label)} on a ${pattern.size} by ${pattern.size} board; filled squares at ${esc(positions)}" style="--size:${pattern.size}">${Array.from({length:pattern.size*pattern.size},(_,i)=>`<span class="${cells.has(`${Math.floor(i/pattern.size)},${i%pattern.size}`)?'filled':''}"></span>`).join('')}</div>`}
function choiceOrder(items,answer,seed,correctDisplayIndex=null){const shift=correctDisplayIndex==null?spatialChoiceIndex(seed,items.length):(answer-correctDisplayIndex+items.length)%items.length,tagged=items.map((x,i)=>({x,correct:i===answer}));return tagged.slice(shift).concat(tagged.slice(0,shift))}
function patternChoices(correct,start,seed,attr,correctDisplayIndex=null){let p=start;const items=[correct,start];p={...start,cells:rotateCellsClockwise(start.cells,start.size)};p={...start,cells:rotateCellsClockwise(p.cells,p.size)};if(!items.some(x=>sameCells(x.cells,p.cells)))items.push(p);while(items.length<3){p={...start,cells:rotateCellsClockwise(p.cells,p.size)};if(!items.some(x=>sameCells(x.cells,p.cells)))items.push(p)}const answer=items.findIndex(x=>sameCells(x.cells,correct.cells));return `<div class="spatial-choice-grid">${choiceOrder(items,answer,seed,correctDisplayIndex).map(({x,correct})=>`<button class="spatial-choice" data-${attr}="${correct?'correct':'wrong'}">${cellBoard(x,'Answer option')}</button>`).join('')}</div>`}
function profile(values,label){return `<div class="profile-card"><strong>${label}</strong><div class="profile-bars">${values.map(n=>`<span style="--h:${n}"><b>${n}</b></span>`).join('')}</div></div>`}
function model(grid,showProfiles=true){const cols=Math.max(...grid.map(r=>r.length)),displayRows=displayRowsBackToFront(grid);return `<div class="spatial-model"><div><strong>Top map · numbers are stack heights</strong><div class="map-direction back">BACK</div><div class="map-middle"><b>LEFT</b><div class="height-map" style="--cols:${cols}">${displayRows.flatMap((row,displayR)=>{const r=grid.length-1-displayR;return Array.from({length:cols},(_,c)=>{const n=row[c]||0,rowName=r===0?'front row 1':r===grid.length-1?'back row':`row ${r+1}`;return `<span class="${n?'':'empty'}" data-source-row="${r+1}"><small>${rowName}</small><b>${n||'—'}</b></span>`})}).join('')}</div><b>RIGHT</b></div><div class="map-direction front">FRONT · ROW 1</div><div class="view-key"><span>FRONT ↥ read columns LEFT → RIGHT</span><span>RIGHT SIDE ↤ read rows FRONT → BACK</span></div></div>${showProfiles?`<div class="profile-pair">${profile(frontView(grid),'Front silhouette · left → right')}${profile(sideView(grid),'Right-side silhouette · front → back')}</div>`:''}</div>`}
function modelChoices(c,seed,attr,correctDisplayIndex=null){return `<div class="model-choice-grid">${choiceOrder(c.candidates,c.answer,seed,correctDisplayIndex).map(({x,correct},i)=>`<button class="model-choice" data-${attr}="${correct?'correct':'wrong'}"><span>Model ${i+1}</span>${model(x,false)}</button>`).join('')}</div>`}
function textChoices(correct,decoys,attr,seed){const items=[correct,...decoys];return `<div class="answer-grid">${choiceOrder(items,0,seed).map(({x,correct})=>`<button class="choice" data-${attr}="${correct?'correct':'wrong'}">${esc(x)}</button>`).join('')}</div>`}
function proof(c){return `The pattern makes one clockwise quarter-turn without flipping. Among the three choices, the selected structure matches front heights ${c.clues.front.join(', ')}, right-side heights ${c.clues.side.join(', ')}, and ${c.clues.total} cubes in all. Other unshown structures might share those clues.`}
function proofDecoys(c){return[`The front heights match, so the side view and total do not need checking.`,`The structure looks similar from above, so hidden stack heights can be ignored.`]}

function renderDiagnostic(){const d=state.diagnostic;if(d.index>=SPATIAL_DIAGNOSTIC.length){state.track=state.track||recommendSpatialTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful spatial challenges. It is not a grade label or test score.</p><button class="primary" data-action="start">Start turning patterns →</button></div>`;return}const q=SPATIAL_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/SPATIAL_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${SPATIAL_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Picture the movement before choosing.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'That relationship is clear.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},450)})}
function renderTurn(c=track().case,fresh=false,challenge=false){const forced=fresh?freshSpatialChoiceIndex(track().id,'pattern',challenge,3):null;$('#activity').innerHTML=`<p class="eyebrow">${fresh?'CHANGED PATTERN':'MENTAL ROTATION'}</p><h3>Turn this entire pattern one quarter-turn clockwise. Do not flip it.</h3><div class="turn-stage">${cellBoard(c.rotation,'Starting pattern')}<b>↻</b><span>?</span></div>${patternChoices(c.turned,c.rotation,`${track().id}:${fresh}`,fresh?'fresh-turn':'turn',forced)}${controls()}${hint('Imagine the top edge moving to the right edge. Every filled square must stay connected in the same way.')}`;const selector=fresh?'[data-fresh-turn]':'[data-turn]';document.querySelectorAll(selector).forEach(b=>b.onclick=()=>{if((fresh?b.dataset.freshTurn:b.dataset.turn)==='correct'){if(fresh){work={...work,rotation:true};saveSession();feedback('The changed pattern kept its shape through the turn.','good');setTimeout(renderMission,350)}else{feedback('Correct—the pattern turned without being flipped.','good');complete(1,['rotation'])}}else miss('That option flips the pattern or moves only part of it. Try tracking one corner square.')})}
function renderViews(){const c=track().case;if(!work.front){$('#activity').innerHTML=`<p class="eyebrow">FRONT VIEW</p><h3>Look from the FRONT edge. Read LEFT to RIGHT. Which heights form the silhouette?</h3>${model(c.model,false)}${textChoices(c.clues.front.join(' – '),[c.clues.front.slice().reverse().join(' – '),String(c.clues.total)],'front','front:'+track().id)}${controls()}${hint('For each front column, keep only the tallest stack you can see in that line. Read the columns left to right.')}`;document.querySelectorAll('[data-front]').forEach(b=>b.onclick=()=>{if(b.dataset.front==='correct'){work={...work,front:true};saveSession();feedback('You found the tallest stack in each front column, left to right.','good');setTimeout(renderMission,350)}else miss('The front silhouette uses one tallest height per column, read left to right—not the total cubes.')});return}$('#activity').innerHTML=`<p class="eyebrow">RIGHT-SIDE VIEW</p><h3>Now walk to the RIGHT edge. Read FRONT to BACK. Which heights form that silhouette?</h3>${model(c.model,false)}${textChoices(c.clues.side.join(' – '),[c.clues.side.slice().reverse().join(' – '),String(c.clues.total)],'side','side:'+track().id)}${controls()}${hint('From the right, each row becomes one visible height. Start with front row 1, then move toward the back.')}`;document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{if(b.dataset.side==='correct'){feedback('The same build makes a different silhouette from the side, read front to back.','good');complete(2,['views'])}else miss('Change your line of sight: from the right, compare each row and read from front to back.')})}
function renderCombine(c=track().case,fresh=false,challenge=false){const stage=fresh?'fresh-model':'model',forced=fresh?freshSpatialChoiceIndex(track().id,'model',challenge,3):null;if(!fresh&&work.model){$('#activity').innerHTML=`<p class="eyebrow">CHECK THE STRENGTH OF THE EVIDENCE</p><h3>What do these clues really prove?</h3>${textChoices('Only one of these three choices fits. A different unshown structure could still share both silhouettes and the same total.',['The clues prove there is only one possible structure anywhere.','Matching the front view proves the hidden stacks, so the other clues are optional.'],'conclusion',track().id+':conclusion')}${controls()}${hint('Ask whether the clues rule out every possible hidden arrangement—or only the choices you can see.')}`;document.querySelectorAll('[data-conclusion]').forEach(b=>b.onclick=()=>{if(b.dataset.conclusion==='correct'){feedback('Exactly. Strong reasoning also says what the evidence cannot prove.','good');complete(3,['constraints'],true)}else miss('The clues eliminate the other shown choices, but hidden arrangements can still share the same silhouettes and total.')});return}$('#activity').innerHTML=`<p class="eyebrow">COMBINE CONSTRAINTS</p><h3>Which of these three models matches ALL three clues?</h3><div class="clue-strip">${profile(c.clues.front,'Front · left → right')}${profile(c.clues.side,'Right side · front → back')}<div class="total-clue"><b>${c.clues.total}</b><span>cubes total</span></div></div>${modelChoices(c,`${track().id}:${fresh}`,stage,forced)}${controls()}${hint('Cross out any shown model when even one clue fails. Matching only the front view is not enough.')}`;document.querySelectorAll(`[data-${stage}]`).forEach(b=>b.onclick=()=>{const value=fresh?b.dataset.freshModel:b.dataset.model;if(value==='correct'){if(fresh){work={...work,model:true};saveSession();feedback('Among these choices, all three clues agree. Now explain what that proves.','good');setTimeout(renderMission,350)}else{work={...work,model:true};saveSession();feedback('This is the only shown model that fits. Now decide whether the clues prove it is the only possible model.','good');setTimeout(renderMission,350)}}else miss('That shown model fails at least one clue. Check front, right side, and total separately.')})}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the viewpoint rules have faded from memory.</strong><p>About ${hours} hours remain. Waiting checks whether the learner can rebuild the reasoning instead of copying today’s answer.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">Preview work uses a different case and cannot count as delayed evidence.</p></div>`;return}const c=ready?track().fresh.challenge:track().fresh.preview;if(!work.rotation){renderTurn(c,true,ready);return}if(!work.model){renderCombine(c,true,ready);return}$('#activity').innerHTML=`<p class="eyebrow">PROVE THE CHANGED CASE</p><h3>Which explanation uses every spatial clue?</h3>${model(c.model,true)}${textChoices(proof(c),proofDecoys(c),'fresh-proof',`${track().id}:proof:${ready}`)}${controls()}${hint('A complete proof names the turn, both viewpoint silhouettes, and the cube total.')}`;document.querySelectorAll('[data-fresh-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.freshProof==='correct'){feedback(ready?'You transferred the spatial reasoning to a changed case after a delay.':'Preview complete. Return later for fresh evidence.','good');complete(4,['rotation','views','constraints','transfer'],false,!ready)}else miss('That explanation trusts one view or appearance. Use every clue.')})}
function renderComplete(i){const m=SPATIAL_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>${i===3?'A fresh challenge unlocks after a delay so memory, not copying, is checked.':'The reasoning is saved for this learner.'}</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':''}</div>`}
function renderMission(){const i=state.activeMission,m=SPATIAL_CHAIN.missions[i],freshReady=i===4&&Boolean(state.retestDue)&&Date.now()>=state.retestDue,sessionKey=i===4?`${m.id}:${freshReady?'challenge':'preview'}`:m.id;if(sessionMissionId!==sessionKey)loadSession(sessionKey);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderTurn();else if(i===2)renderViews();else if(i===3)renderCombine();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=SPATIAL_CHAIN.missions.map((m,i)=>`<button class="mission-button ${state.activeMission===i?'active':''} ${done(i)?'done':''}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(SPATIAL_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankSpatialLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const name=learner==='a'?'Ella':'Mila',labels={rotation:'Mental rotation',views:'Read two viewpoints',constraints:'Combine all constraints',transfer:'Fresh spatial transfer'};$('#evidenceTitle').textContent=`${name}’s learning evidence`;$('#reviewBannerTitle').textContent=`Built for ${name} · waiting family review`;$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['spatial-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='preview'){state.previewFresh=true;save();render()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankSpatialLearner();sessionMissionId=null;ensureState();saveLearnerChoice();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the spatial review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankSpatialLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();
